        const SCRIPT: &str = include_str!("../../../scripts/macos-bundle-updater.sh");
        assert!(
            SCRIPT.starts_with("#!/bin/bash"),
            "updater script must start with a shebang"
        );
        assert!(
            SCRIPT.contains("macOS DMG-swap updater"),
